import{_ as n,c as e,o as s,ag as i}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Admin","description":"","frontmatter":{"title":"Admin"},"headers":[],"relativePath":"general/admin.md","filePath":"general/admin.md","lastUpdated":null}'),r={name:"general/admin.md"};function t(l,a,o,p,c,u){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h1><h3 id="quick-admin-links" tabindex="-1">Quick Admin Links <a class="header-anchor" href="#quick-admin-links" aria-label="Permalink to &quot;Quick Admin Links&quot;">​</a></h3><p>For Admin, See the <a href="https://mod.irregular.chat" target="_blank" rel="noreferrer">Mod Portal</a> to create users and more</p><ul><li><p>*&#39;&#39;<a href="/ai-ml/ai-prompting.html">Chat Message Prompts</a></p></li><li><p><a href="/general/links.html">Links</a> with all the chats</p></li><li><p><a href="/community/welcome.html">Page</a></p></li><li><p><a href="https://forum.irregularchat.com" target="_blank" rel="noreferrer">IrregularChat Forum</a></p></li></ul><p>Add ?all to the URL to temporarily use it and bypass the SSO. # Group Admins</p><p>Thanks for being an admin. You have your day job, and this is not intended to take much of your time.</p><p>The goal is to provide additional resources to those interested in expanding their proficiency. The Wiki and the GitLab can help users greatly in that regard, as so much information gets put out and may need help finding its way to the right people.</p><h2 id="copy-and-paste-for-situation" tabindex="-1">Copy and Paste For Situation <a class="header-anchor" href="#copy-and-paste-for-situation" aria-label="Permalink to &quot;Copy and Paste For Situation&quot;">​</a></h2><h3 id="individual-requests-to-join-chat" tabindex="-1">Individual Requests to Join Chat <a class="header-anchor" href="#individual-requests-to-join-chat" aria-label="Permalink to &quot;Individual Requests to Join Chat&quot;">​</a></h3><p>As an admin, you help add and confirm people are coming from the community. Confirming someone who requests to join is as easy as using the following:</p><h3 id="moderation-messages" tabindex="-1">Moderation Messages <a class="header-anchor" href="#moderation-messages" aria-label="Permalink to &quot;Moderation Messages&quot;">​</a></h3><h3 id="encourage-nipr-sipr-jwics-for-knowledge-management" tabindex="-1">Encourage NIPR/SIPR/JWICS for Knowledge Management <a class="header-anchor" href="#encourage-nipr-sipr-jwics-for-knowledge-management" aria-label="Permalink to &quot;Encourage NIPR/SIPR/JWICS for Knowledge Management&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Are you on the NIPR or higher Milsuite or Chatsurfer?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>🍀</span></span>
<span class="line"><span>Direct NIPR Link Chatsurfer: https://url.irregular.chat/chatsurfer</span></span>
<span class="line"><span>Direct NIPR Link Milsuite: https://url.irregular.chat/msuite</span></span>
<span class="line"><span>👹</span></span>
<span class="line"><span>Direct SIPR Link Chatsurfer: (access via SIPR network)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>or search &amp;quot;irregular chat&amp;quot; on chatsurfer NIPR SIPR or higher</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Perfect for sharing on the appropriate level while still breaking down silos and being found by others working on these same topics</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><ul><li><strong><a href="/general/admin.html">To Top</a></strong></li></ul><h3 id="send-off-topic" tabindex="-1">Send Off Topic <a class="header-anchor" href="#send-off-topic" aria-label="Permalink to &quot;Send Off Topic&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🌟Community Reminder🌟</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hey everyone! Our group thrives on technical discussions, sharing knowledge, and building cool projects together.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>We understand everyone likes a good laugh or a casual chat now and then beyond the room&#39;s topic, which is why we&#39;ve got a special place just for that!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If you&#39;re itching for off-topic banter or to share the latest meme, head over to our off-topic chat: https://url.irregular.chat/otg.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>It&#39;s the perfect spot for relaxing and diverging from a specific topic of chatter.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If you&#39;re not interested in the technical aspects, no worries! We want everyone to find their best fit, and there are no hard feelings if this isn&#39;t your place.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Let&#39;s keep our main chat focused on tech to ensure it remains a valuable resource for everyone.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Thanks for being such an awesome part of our journey. Let&#39;s keep pushing the boundaries of what we can achieve together! 🚀</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><ul><li><strong><a href="/general/admin.html">To Top</a></strong></li></ul><h3 id="bonafides" tabindex="-1">Bonafides <a class="header-anchor" href="#bonafides" aria-label="Permalink to &quot;Bonafides&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You&#39;ve requested to join the Irregular Chat.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bonafides: Everyone in the chat has been invited by another who they personally know. So that we can add you to the right groups, we need to know:</span></span>
<span class="line"><span>## Who you are</span></span>
<span class="line"><span>2. Where you are from</span></span>
<span class="line"><span>3. Who invited you</span></span>
<span class="line"><span></span></span>
<span class="line"><span>As you send your intro, feel free to ask any questions about the community</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li><strong><a href="/general/admin.html">To Top</a></strong></li></ul><h3 id="safety-number-change" tabindex="-1">Safety Number Change <a class="header-anchor" href="#safety-number-change" aria-label="Permalink to &quot;Safety Number Change&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>It shows that your safety number has changed. For the privacy and security of all, we ask that you provide one of the following:</span></span>
<span class="line"><span>- Your details. Name, organization, and who added you</span></span>
<span class="line"><span>- Your IrregularChat Element Messenger username that we can verify</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If you don&#39;t reply to this message in 24 hours, your account will be removed from the chats, and you can request to join again when you are ready.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><strong><a href="/general/admin.html">To Top</a></strong></li></ul><h3 id="removal-due-to-not-verifying-a-safety-number" tabindex="-1">Removal due to not verifying a safety number <a class="header-anchor" href="#removal-due-to-not-verifying-a-safety-number" aria-label="Permalink to &quot;Removal due to not verifying a safety number&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NAME is being removed for not verifying themselves after their safety number changed. This is done to maintain the integrity of the community. This could mean the number was assigned to a different person or their SIM was put into a different device.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>They are welcome to request to join anytime but will need to be verified by knowing someone in the community and providing their name and organization</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li><strong><a href="/general/admin.html">To Top</a></strong></li></ul><h3 id="diagram-of-irregular-wiki-concept" tabindex="-1">Diagram of Irregular Wiki Concept <a class="header-anchor" href="#diagram-of-irregular-wiki-concept" aria-label="Permalink to &quot;Diagram of Irregular Wiki Concept&quot;">​</a></h3><ul><li>Current Wiki Flowchart (see site navigation)</li></ul><p>[Required]</p>`,29)])])}const m=n(r,[["render",t]]);export{d as __pageData,m as default};
